type Ev =
  | { kind: 'enemy-died'; id: number }
  | { kind: 'sound'; id: SoundId; volume: number };

const pending: Ev[] = [];
const post = (e: Ev): void => { pending.push(e); };

function handle(e: Ev): void {
  switch (e.kind) {
    case 'enemy-died': loot(e.id); break;
    case 'sound': play(e.id, e.volume);
  }
}
